-- Returns the expected timeline in the recorded-timeline shape: events {time, spell}, sorted.
-- Built once per boss and difficulty: the pages ask for it on every redraw.
local cache = {}
function ns.ExpectedTimeline(encounter, difficulty)
    local key = tostring(encounter) .. ":" .. (difficulty == 16 and 2 or 1)
    if cache[key] == nil then cache[key] = ns.BuildExpectedTimeline(encounter, difficulty) or false end
    return cache[key] or nil
end
function ns.BuildExpectedTimeline(encounter, difficulty)
    local boss = T[tonumber(encounter)]
    local data = boss and boss[difficulty == 16 and 2 or 1]
    if not data or #data.events == 0 then return nil end
    local events, length = {}, 0
    for _, e in ipairs(data.events) do
        for _, at in ipairs(e[2]) do events[#events + 1] = { at, e[1] }; if at > length then length = at end end
    end
    table.sort(events, function(a, b) if a[1] ~= b[1] then return a[1] < b[1] end return a[2] < b[2] end)
    local phases = {}
    for _, p in ipairs(data.phases) do phases[#phases + 1] = { name = p[1], at = p[2] } end
    return { events = events, length = length, phases = phases, expected = true }
end
